path([[ex-75,ey+2],[ex-77,ey-54],[ex-66,ey-104],[ex-41,ey-135],[ex-5,ey-149],[ex+33,ey-139],[ex+63,ey-110],[ex+77,ey-67],[ex+73,ey+2]],'#415448','#7d8b65',3);
