for(const e of enemies)if(e.x>camX-80&&e.x<camX+W+80)enemy(e);hero(follower.x,follower.y,true,p.dir,false);hero(p.x,p.y,false,p.dir,true);for(const s of shots){if(s.type==='dart')drawPea(s);else circle(s.x,s.y,s.type==='bomb'?7:5,s.type==='bomb'?'#d6ae56':'#c3cab0')}for(const a of particles)circle(a.x,a.y,2,a.color);ctx.restore();
