// Use the same character drawing for portraits and the cave sprites.
function drawPortraits(){
  const caveContext=ctx;
  try{
    for(const [id,donald] of [['brandPortrait',false],['stickolasPortrait',false],['donaldPortrait',true]]){
      const portrait=$(id);
      ctx=portrait.getContext('2d');
      ctx.clearRect(0,0,portrait.width,portrait.height);
      ctx.save();
      ctx.translate(48,112);
      ctx.scale(1.5,1.5);
      hero(0,donald?12:30,donald,1,false,true);
      ctx.restore();
    }
  }finally{ctx=caveContext}
}
drawPortraits();
// Read-only diagnostics for local verification.
window.expedition={get state(){return{level,score,cols,rows,mode,p:{...p},ammo:{...ammo},weaponTiers:{...weaponTiers},lightBoost,equipped,heroes:heroes.map(h=>({...h})),enemies:enemies.filter(e=>e.hp>0).length}},get maze(){return cells.map(a=>({...a}))}};
